+
+int HID_GetDescriptor(int8_t t)
+{
+	if (HID_REPORT_DESCRIPTOR_TYPE == t) {
+		HIDDescriptorListNode* current = rootNode;
+		int total = 0;
+		while(current != NULL) {
+			total += USB_SendControl(TRANSFER_PGM,current->cb->descriptor,current->cb->length);
+			current = current->next;
+		}
+		return total;
+	} else {
+		return 0;
+	}
+}
