+void HID_::AppendDescriptor(HIDDescriptorListNode *node)
+{
+	if (modules_count == 0) {
+		rootNode = node;
+	} else {
+		HIDDescriptorListNode *current = rootNode;
+		while(current->next != NULL) {
+			current = current->next;
+		}
+		current->next = node;
+	}
+	modules_count++;
+	sizeof_hidReportDescriptor += node->cb->length;
+}
